{"file_path":"src/parse.js","content":"/** Parsing of the election input into candidates and ballots. */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(message) {
  throw new ParseError(message)
}

/**
 * Split the raw input into logical lines, dropping the empty tail that a
 * trailing newline leaves behind.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse an election. Returns { candidates: string[], ballots: [{count, ranking}] }.
 * Throws ParseError with the exact user-facing message on the first problem.
 */
export function parseElection(text) {
  const lines = splitLines(text)
  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      const names = words.slice(1)
      if (names.length === 0) fail(`line ${lineNo}: expected candidates <name>...`)
      for (const name of names) {
        if (!NAME_RE.test(name)) fail(`line ${lineNo}: invalid candidate name ${name}`)
        if (declared.has(name)) fail(`line ${lineNo}: candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names.slice()
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 3) fail(`line ${lineNo}: expected ballot <count> <candidate>...`)
      const countWord = words[1]
      if (!COUNT_RE.test(countWord)) fail(`line ${lineNo}: count must be a positive integer`)
      const count = Number(countWord)
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) fail(`line ${lineNo}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${lineNo}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count, ranking })
    } else {
      fail(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

function byCodePoint(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/**
 * Run the count. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, continuing: string[], exhausted, eliminated }.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }
    let active = 0
    for (const votes of counts.values()) active += votes

    const round = {
      counts,
      continuing: candidates.filter((name) => continuing.has(name)),
      exhausted,
      eliminated: null
    }
    rounds.push(round)

    if (active === 0) break

    let leader = null
    for (const [name, votes] of counts) {
      if (votes * 2 > active) leader = name
    }
    if (leader !== null) {
      winner = leader
      break
    }

    const eliminated = chooseElimination(round.continuing, rounds)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/** Pick the candidate to eliminate, resolving ties over the rounds so far. */
function chooseElimination(continuing, rounds) {
  const last = rounds[rounds.length - 1].counts
  let fewest = Infinity
  for (const name of continuing) fewest = Math.min(fewest, last.get(name))
  let tied = continuing.filter((name) => last.get(name) === fewest)
  if (tied.length === 1) return tied[0]

  for (;;) {
    let separated = false
    for (const round of rounds) {
      const values = tied.map((name) => round.counts.get(name))
      const min = Math.min(...values)
      if (values.some((value) => value !== min)) {
        tied = tied.filter((name) => round.counts.get(name) === min)
        if (tied.length === 1) return tied[0]
        separated = true
        break
      }
    }
    if (!separated) break
  }

  return tied.slice().sort(byCodePoint)[tied.length - 1]
}

/** Order a round's candidates: descending votes, then ascending name. */
export function orderRound(round) {
  return round.continuing.slice().sort((a, b) => {
    const diff = round.counts.get(b) - round.counts.get(a)
    if (diff !== 0) return diff
    return byCodePoint(a, b)
  })
}
"}

