import { tokenize, LexError } from './lexer.js'
import { splitWord } from './address.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_ARITY = { SUM: 'many', MIN: 'many', MAX: 'many', COUNT: 'many', AVG: 'many', ABS: 1, IF: 3 }

function isWordOp(word, target) {
  return word.toUpperCase() === target
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  parseFormula() {
    const expr = this.parseExpr()
    if (this.pos !== this.tokens.length) {
      throw new ParseError('trailing tokens')
    }
    return expr
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && COMPARISON_OPS.has(t.value)) {
        this.next()
        const right = this.parseAdditive()
        left = { kind: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.value === '+' || t.value === '-')) {
        this.next()
        const right = this.parseMultiplicative()
        left = { kind: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.value === '*' || t.value === '/')) {
        this.next()
        const right = this.parsePower()
        left = { kind: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    const t = this.peek()
    if (t && t.type === 'OP' && t.value === '^') {
      this.next()
      const right = this.parsePower()
      return { kind: 'binop', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'OP' && (t.value === '+' || t.value === '-')) {
      this.next()
      const operand = this.parseUnary()
      return { kind: 'unop', op: t.value, operand }
    }
    return this.parsePrimary()
  }

  // Try to parse a range (WORD COLON WORD) where neither word is a call or
  // TRUE/FALSE. Returns a range node or null (restoring position) if it
  // doesn't match.
  tryParseRange() {
    const start = this.pos
    const w1 = this.peek()
    if (!w1 || w1.type !== 'WORD') return null
    if (isWordOp(w1.value, 'TRUE') || isWordOp(w1.value, 'FALSE')) return null
    const after1 = this.peek(1)
    if (after1 && after1.type === 'LPAREN') return null
    if (!after1 || after1.type !== 'COLON') return null
    const w2 = this.peek(2)
    if (!w2 || w2.type !== 'WORD') return null
    if (isWordOp(w2.value, 'TRUE') || isWordOp(w2.value, 'FALSE')) return null
    const after2 = this.peek(3)
    if (after2 && after2.type === 'LPAREN') return null
    this.pos = start + 3
    return { kind: 'range', from: w1.value, to: w2.value }
  }

  parseArgument() {
    const range = this.tryParseRange()
    if (range) return range
    return this.parseExpr()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUMBER') {
      this.next()
      return { kind: 'num', value: Number(t.value) }
    }
    if (t.type === 'LPAREN') {
      this.next()
      const e = this.parseExpr()
      const r = this.peek()
      if (!r || r.type !== 'RPAREN') throw new ParseError('expected )')
      this.next()
      return e
    }
    if (t.type === 'WORD') {
      const after = this.peek(1)
      if (after && after.type === 'LPAREN') {
