        const name = t.value.toUpperCase()
        this.next() // word
        this.next() // (
        const args = []
        const rp = this.peek()
        if (rp && rp.type === 'RPAREN') {
          this.next()
        } else {
          for (;;) {
            args.push(this.parseArgument())
            const sep = this.peek()
