            if (sep && sep.type === 'RPAREN') { this.next(); break }
            throw new ParseError('expected , or ) in call')
          }
        }
        return { kind: 'call', name, args }
      }
      if (isWordOp(t.value, 'TRUE')) { this.next(); return { kind: 'bool', value: true } }
      if (isWordOp(t.value, 'FALSE')) { this.next(); return { kind: 'bool', value: false } }
      this.next()
      const parts = splitWord(t.value)
      return { kind: 'addr', letters: parts.letters, digits: parts.digits, raw: t.value }
    }
    throw new ParseError(`unexpected token`)
  }
}

