import { parseFormula, ParseError, CALL_ARITY } from './parser.js'
import { parseAddressWord, addressToString } from './address.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function numVal(v) { return { type: 'number', value: v } }
export function textVal(v) { return { type: 'text', value: v } }
export function boolVal(v) { return { type: 'bool', value: v } }
export function errVal(v) { return { type: 'error', value: v } }

export function classifyLiteral(content) {
  if (content === '') return numVal(0)
  if (NUMBER_RE.test(content)) return numVal(Number(content))
  if (ERROR_TOKENS.has(content)) return errVal(content)
  return textVal(content)
}

function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return numVal(v.value ? 1 : 0)
  if (v.type === 'text') return errVal('#VALUE!')
  return v // error passthrough
}

function typeRank(t) {
  if (t === 'number') return 0
  if (t === 'text') return 1
  return 2 // bool
}

function compareValues(lv, rv) {
  if (lv.type === rv.type) {
    if (lv.type === 'number') return lv.value < rv.value ? -1 : lv.value > rv.value ? 1 : 0
    if (lv.type === 'text') return lv.value < rv.value ? -1 : lv.value > rv.value ? 1 : 0
    // bool: false < true
    if (lv.value === rv.value) return 0
    return lv.value ? 1 : -1
  }
  return typeRank(lv.type) - typeRank(rv.type)
}

function arith(op, a, b) {
  let r
  if (op === '+') r = a + b
  else if (op === '-') r = a - b
  else if (op === '*') r = a * b
  else if (op === '/') {
    if (b === 0) return errVal('#DIV/0!')
    r = a / b
  } else if (op === '^') {
    r = Math.pow(a, b)
  }
  if (!Number.isFinite(r)) return errVal('#DIV/0!')
  return numVal(r)
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map canonical -> {content, col, row}
    this.astCache = new Map() // canonical -> ast | ERR_SENTINEL
    this.memo = new Map() // canonical -> Value
    this.state = new Map() // canonical -> 'visiting' | 'done'
  }

  getAst(canonical) {
    if (this.astCache.has(canonical)) return this.astCache.get(canonical)
    const cell = this.cells.get(canonical)
    let ast = null
    if (cell && cell.content.startsWith('=')) {
