        return errVal('#ERR!')
      default:
        return errVal('#ERR!')
    }
  }

  evalCall(node) {
    const name = node.name
    const arity = CALL_ARITY[name]
    if (arity === undefined) return errVal('#NAME?')
    if (arity === 'many') {
      if (node.args.length < 1) return errVal('#ERR!')
    } else if (node.args.length !== arity) {
      return errVal('#ERR!')
    }

    if (name === 'IF') {
      const condVals = this.evalArgList(node.args[0])
      const cond = condVals[0]
      if (cond.type === 'error') return cond
      let truthy
      if (cond.type === 'bool') truthy = cond.value
      else if (cond.type === 'number') truthy = cond.value !== 0
