      const branch = truthy ? node.args[1] : node.args[2]
      const vals = this.evalArgList(branch)
      if (vals.length !== 1) return errVal('#ERR!')
      return vals[0]
    }

    // Flatten all argument slots (ranges expanded) in left-to-right order.
    const values = []
    for (const arg of node.args) {
      const vs = this.evalArgList(arg)
      for (const v of vs) values.push(v)
    }

    if (name === 'COUNT') {
      for (const v of values) {
        if (v.type === 'error') return v
      }
      const count = values.filter((v) => v.type === 'number').length
      return numVal(count)
    }

    // ABS, SUM, MIN, MAX, AVG all need numeric coercion.
    const nums = values.map(toNumber)
    for (const v of nums) {
      if (v.type === 'error') return v
    }

    if (name === 'ABS') {
      if (nums.length !== 1) return errVal('#ERR!')
      return numVal(Math.abs(nums[0].value))
    }
    if (name === 'SUM') {
