      for (const v of nums) s += v.value
      return numVal(s)
    }
    if (name === 'MIN') {
      let m = nums[0].value
      for (const v of nums) if (v.value < m) m = v.value
      return numVal(m)
    }
    if (name === 'MAX') {
      let m = nums[0].value
      for (const v of nums) if (v.value > m) m = v.value
      return numVal(m)
    }
    if (name === 'AVG') {
      let s = 0
      for (const v of nums) s += v.value
      return numVal(s / nums.length)
    }
    return errVal('#NAME?')
  }
}
