  const f = parseAddressWord(fromWord)
  const t = parseAddressWord(toWord)
  if (!f || !t || !f.inRange || !t.inRange) return
  const c1 = Math.min(f.col, t.col)
  const c2 = Math.max(f.col, t.col)
  const r1 = Math.min(f.row, t.row)
  const r2 = Math.max(f.row, t.row)
  for (let c = c1; c <= c2; c++) {
    for (let r = r1; r <= r2; r++) {
      set.add(addressToString(c, r))
    }
  }
}

