  switch (node.kind) {
    case 'num':
    case 'bool':
      return
    case 'addr': {
      const p = parseAddressWord(node.raw)
      if (p && p.inRange) set.add(p.canonical)
      return
    }
    case 'range':
      addRangeCells(node.from, node.to, set)
      return
    case 'unop':
      walk(node.operand, set)
      return
    case 'binop':
      walk(node.left, set)
      walk(node.right, set)
      return
    case 'call':
      for (const a of node.args) walk(a, set)
      return
    default:
      return
  }
}

