const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export function isValidToken(str) {
  return typeof str === 'string' && NAME_RE.test(str)
}

// Parses an unsigned decimal integer with no sign and no useless leading
// zero. Returns a BigInt on success, or null when the text is not a valid
// unsigned integer literal at all.
export function parseUnsignedInt(str) {
  if (typeof str !== 'string' || !UINT_RE.test(str)) return null
  return BigInt(str)
}

