{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-6gmSgv/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { run } from './engine.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  try {
    const output = run(input, mode)
    process.stdout.write(output)
    process.exit(0)
  } catch (err) {
    if (err && err.name === 'AppError') {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }
}

main()
"}

