{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ConfError, parseDocument } from './parse.js'
import { toJson, toKeys } from './format.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
  die('usage: cli.js json|keys')
}

let output
try {
  const root = parseDocument(readInput())
  output = argv[0] === 'json' ? toJson(root) : toKeys(root)
} catch (error) {
  if (error instanceof ConfError) die(`line ${error.line}: ${error.reason}`)
  throw error
}

process.stdout.write(output)
"}

