const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d ||
    code === 0x2e ||
    code === 0x5f ||
    code === 0x7e
  )
}

function lowerAscii(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

export function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') {
      out += text[i]
      continue
    }
    const digits = text.slice(i + 1, i + 3)
    if (digits.length < 2 || !HEX.test(digits)) throw new UriError(component)
    const upper = digits.toUpperCase()
    const code = parseInt(upper, 16)
    out += isUnreserved(code) ? String.fromCharCode(code) : `%${upper}`
    i += 2
  }
  return out
}

export function parseUri(text) {
  let rest = text
  let scheme = null
  const stop = rest.search(/[/?#]/)
  const colon = rest.indexOf(':')
  if (colon >= 0 && (stop < 0 || colon < stop)) {
    scheme = rest.slice(0, colon)
    rest = rest.slice(colon + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = rest.search(/[/?#]/)
    if (end < 0) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, end)
      rest = rest.slice(end)
    }
  }

  let fragment = null
  const hash = rest.indexOf('#')
