{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { checkUri, normalizeUri, resolveUri, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function splitRecords(input) {
  if (input === '') return []
  const text = input.endsWith('\n') ? input.slice(0, -1) : input
  return text.split('\n')
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = argv[0]
  const records = splitRecords(readStdin())
  const lines = []

  for (let i = 0; i < records.length; i += 1) {
    const record = records[i]
    const number = i + 1
    try {
      if (mode === 'normalize') {
        lines.push(normalizeUri(checkUri(record)))
      } else {
        const space = record.indexOf(' ')
        if (space < 0) fail(`line ${number}: expected a base and a reference`)
        const baseText = record.slice(0, space)
        const refText = record.slice(space + 1)
        const base = checkUri(baseText)
        if (base.scheme === null) fail(`line ${number}: the base has no scheme`)
        const ref = checkUri(refText)
        lines.push(resolveUri(base, ref))
      }
    } catch (error) {
      if (error instanceof UriError) fail(`line ${number}: ${error.message}`)
      throw error
    }
  }

  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

