    lines[i] = line
    columns[i] = column
    const c = cps[i]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
  }
  return { lines, columns }
}

