    t.scheme = ref.scheme
    t.authority = ref.authority
    t.path = ref.path
    t.query = ref.query
  } else if (ref.authority !== undefined) {
    t.scheme = base.scheme
    t.authority = ref.authority
    t.path = ref.path
    t.query = ref.query
  } else if (ref.path === '') {
    t.scheme = base.scheme
    t.authority = base.authority
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path.startsWith('/')) {
      t.path = ref.path
    } else {
      t.path = mergePaths(base, ref.path)
    }
    t.query = ref.query
  }
  t.fragment = ref.fragment
