{"file_path":"src/pack.js","content":"import { compareNames } from './parse.js'

/**
 * Greedy list scheduling onto a fixed number of workers: at every instant the
 * ready task with the greatest priority (ties by ascending name) goes to the
 * free worker with the smallest index.
 */
export function pack(graph, info, workerCount) {
  const { names, cost, deps } = graph
  const free = new Array(workerCount).fill(0) // the instant each worker is idle again
  const runs = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const pending = new Set(names)

  let time = 0
  let makespan = 0

  while (pending.size > 0) {
    for (;;) {
      const worker = free.findIndex((at) => at <= time)
      if (worker === -1) break

      let best = null
      for (const name of pending) {
        let ready = true
        for (const dep of deps.get(name)) {
          if (!finish.has(dep) || finish.get(dep) > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          info.priority.get(name) > info.priority.get(best) ||
          (info.priority.get(name) === info.priority.get(best) && compareNames(name, best) < 0)
        ) {
          best = name
        }
      }
      if (best === null) break

      const end = time + cost.get(best)
      runs[worker].push(`${best}@${time}-${end}`)
      free[worker] = end
      finish.set(best, end)
      pending.delete(best)
      if (end > makespan) makespan = end
    }

    if (pending.size === 0) break

    let next = null
    for (const at of free) {
      if (at > time && (next === null || at < next)) next = at
    }
    if (next === null) break // nothing can ever start; the graph was acyclic, so unreachable
    time = next
  }

  const lines = runs.map((list, i) => `worker ${i}:${list.map((run) => ` ${run}`).join('')}`)
  lines.push(`makespan ${makespan}`)
  return lines.map((line) => `${line}\n`).join('')
}
"}

