{"file_path":"src/schedule.js","content":"/**
 * Simulate the graph on a fixed number of workers, always starting the ready
 * task whose chain is longest, ties going to the smaller name.
 *
 * @param {{ names: string[], cost: Map<string, number>, deps: Map<string, string[]> }} graph
 * @param {Map<string, number>} priority the longest chain beginning at each task
 * @param {number} workers how many workers are available
 * @returns {{ runs: { name: string, start: number, finish: number }[][], makespan: number }}
 */
export function pack(graph, priority, workers) {
  const free = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  const done = new Map()
  const pending = new Set(graph.names)
  let makespan = 0
  let time = 0

  while (pending.size > 0) {
    for (;;) {
      const worker = free.findIndex((when) => when <= time)
      if (worker === -1) break
      let best = null
      for (const name of pending) {
        const deps = graph.deps.get(name) ?? []
        if (!deps.every((dep) => done.has(dep) && done.get(dep) <= time)) continue
        if (best === null) {
          best = name
          continue
        }
        const gap = priority.get(name) - priority.get(best)
        if (gap > 0 || (gap === 0 && name < best)) best = name
      }
      if (best === null) break
      const finish = time + graph.cost.get(best)
      runs[worker].push({ name: best, start: time, finish })
      free[worker] = finish
      done.set(best, finish)
      pending.delete(best)
      if (finish > makespan) makespan = finish
    }
    if (pending.size === 0) break
    let next = null
    for (const when of free) {
      if (when > time && (next === null || when < next)) next = when
    }
    if (next === null) break
    time = next
  }

  return { runs, makespan }
}
"}

{"file_path":"src/report.js","content":"/**
 * The `waves` report: the tasks grouped by depth, then the makespan.
 *
 * @param {{ names: string[] }} graph the parsed build graph
 * @param {{ depth: Map<string, number>, total: number }} analysis its timings
 * @returns {string} the whole of standard output
 */
export function waves(graph, analysis) {
  const groups = []
  for (const name of graph.names) {
    const level = analysis.depth.get(name)
    while (groups.length <= level) groups.push([])
    groups[level].push(name)
  }
  const lines = groups.map((group, level) => `wave ${level}: ${group.join(' ')}`)
  lines.push(`total ${analysis.total}`)
  return lines.map((line) => `${line}\n`).join('')
}

/**
 * The `explain` report: one line per task in name order, then the makespan.
 *
 * @param {{ names: string[] }} graph the parsed build graph
 * @param {{ start: Map<string, number>, finish: Map<string, number>, depth: Map<string, number>, total: number }} analysis
 * @returns {string} the whole of standard output
 */
export function explain(graph, analysis) {
  const lines = graph.names.map(
    (name) =>
      `${name} start=${analysis.start.get(name)} finish=${analysis.finish.get(name)}` +
      ` depth=${analysis.depth.get(name)}`,
  )
  lines.push(`total ${analysis.total}`)
  return lines.map((line) => `${line}\n`).join('')
}

/**
 * The `pack` report: one line per worker, then the makespan.
 *
 * @param {{ runs: { name: string, start: number, finish: number }[][], makespan: number }} schedule
 * @returns {string} the whole of standard output
 */
export function packed(schedule) {
  const lines = schedule.runs.map(
    (runs, index) =>
      `worker ${index}:` + runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join(''),
  )
  lines.push(`makespan ${schedule.makespan}`)
  return lines.map((line) => `${line}\n`).join('')
}
"}

