{"file_path":"src/cli.js","content":"import { parse, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let read
    try {
      read = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (read === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, read)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'replay' && argv[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = argv[0]

  const text = readStdin()
  let program
  try {
    program = parse(text)
  } catch (err) {
    if (err instanceof ParseError) fail(err.message)
    throw err
  }

  const results = simulate(program)
  const out = []
  if (mode === 'replay') {
    for (const r of results) {
      out.push(r.allowed ? `${r.tick} ${r.key} allow\n` : `${r.tick} ${r.key} deny ${r.by}\n`)
    }
  } else {
    const counts = new Map()
    let allowed = 0
    let denied = 0
    for (const r of results) {
      let entry = counts.get(r.key)
      if (entry === undefined) {
        entry = { allowed: 0, denied: 0 }
        counts.set(r.key, entry)
      }
      if (r.allowed) {
        entry.allowed += 1
        allowed += 1
      } else {
        entry.denied += 1
        denied += 1
      }
    }
    const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    for (const key of keys) {
      const entry = counts.get(key)
      out.push(`${key} allowed=${entry.allowed} denied=${entry.denied}\n`)
    }
    out.push(`total allowed=${allowed} denied=${denied}\n`)
  }
  process.stdout.write(out.join(''))
}

main()
"}

