}

function scanBlockComment(sc) {
  const start = sc.pos()
  sc.advance() // '/'
  sc.advance() // '*'
  let depth = 1
  while (depth > 0) {
    if (sc.eof()) sc.error(start, 'unterminated block comment')
    if (sc.peek() === '/' && sc.peek(1) === '*') {
      sc.advance()
      sc.advance()
      depth++
      continue
    }
    if (sc.peek() === '*' && sc.peek(1) === '/') {
      sc.advance()
      sc.advance()
      depth--
      continue
    }
    sc.advance()
  }
}

function scanPunct(sc) {
  const start = sc.pos()
  const c0 = sc.peek()
  const c1 = sc.peek(1)
  const two = c1 !== undefined ? c0 + c1 : undefined
  if (two !== undefined && PUNCT2.includes(two)) {
    sc.advance()
    sc.advance()
    return { kind: 'punct', line: start.line, col: start.col, text: two }
  }
  if (PUNCT1.includes(c0)) {
    sc.advance()
    return { kind: 'punct', line: start.line, col: start.col, text: c0 }
  }
  sc.error(start, `unexpected character ${c0}`)
}

export function scan(input) {
  const sc = new Scanner(input)
  const tokens = []
  while (!sc.eof()) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '/') {
      sc.advance()
      sc.advance()
      while (!sc.eof() && sc.peek() !== '\n') sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '*') {
      scanBlockComment(sc)
      continue
    }
    if (c === '"') {
      tokens.push(scanString(sc))
      continue
    }
    if (c === 'r' && sc.peek(1) === '"') {
      tokens.push(scanRawString(sc))
      continue
    }
    if (isIdentStart(c)) {
      tokens.push(scanIdent(sc))
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(sc))
      continue
    }
    tokens.push(scanPunct(sc))
  }
  return tokens
}
"}

