{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync, writeSync } from 'node:fs'
import { ParseError, parseDocument } from './parse.js'
import { toJson, toKeys } from './format.js'

function writeAll(fd, text) {
  const buf = Buffer.from(text, 'utf8')
  let off = 0
  while (off < buf.length) off += writeSync(fd, buf, off, buf.length - off)
}

function fail(message) {
  writeAll(2, `error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
  fail('usage: cli.js json|keys')
}

const input = readStdin()
let root
try {
  root = parseDocument(input)
} catch (e) {
  if (e instanceof ParseError) fail(`line ${e.line}: ${e.reason}`)
  throw e
}

writeAll(1, argv[0] === 'json' ? toJson(root) : toKeys(root))
"}

