  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  // bool: false below true
  if (a.v === b.v) return 0
  return a.v ? 1 : -1
}

function finishArith(v) {
  return Number.isFinite(v) ? NUM(v) : ERR('#DIV/0!')
}

export function makeEvaluator(sheet) {
  const cache = new Map()
  const visiting = new Set()

  function evalCell(key) {
    if (cache.has(key)) return cache.get(key)
    if (visiting.has(key)) return ERR('#CYCLE!')
    visiting.add(key)
    let result
    const cell = sheet.get(key)
    if (!cell) {
      result = NUM(0)
    } else if (cell.kind === 'literal') {
      result = cell.literalValue
    } else if (!cell.ast) {
      result = ERR('#ERR!')
    } else {
      result = evalNode(cell.ast)
    }
    visiting.delete(key)
    cache.set(key, result)
    return result
  }

  function evalAddressRef(text) {
    const addr = parseAddress(text)
    if (!addr) return ERR('#REF!')
    return evalCell(addr.key)
  }

  function expandRangeValues(fromText, toText) {
    const addrs = expandRangeAddrs(fromText, toText)
    if (!addrs) return [ERR('#REF!')]
    return addrs.map((a) => evalCell(a.key))
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return NUM(node.value)
      case 'bool':
        return BOOL(node.value)
      case 'ref':
        return evalAddressRef(node.text)
      case 'unary': {
        const operand = toNumber(evalNode(node.operand))
        if (operand.t === 'err') return operand
        const v = node.op === '-' ? -operand.v : +operand.v
        return finishArith(v)
      }
      case 'bin':
        return evalBin(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error('bad node: ' + node.type)
    }
  }

  function evalBin(node) {
    const { op } = node
    if (COMPARE_OPS.has(op)) {
      const l = evalNode(node.left)
      if (l.t === 'err') return l
      const r = evalNode(node.right)
      if (r.t === 'err') return r
      const cmp = compareValues(l, r)
      switch (op) {
        case '=':
          return BOOL(cmp === 0)
        case '<>':
          return BOOL(cmp !== 0)
        case '<':
          return BOOL(cmp < 0)
        case '<=':
          return BOOL(cmp <= 0)
        case '>':
          return BOOL(cmp > 0)
        case '>=':
          return BOOL(cmp >= 0)
      }
    }
    const l = toNumber(evalNode(node.left))
    if (l.t === 'err') return l
    const r = toNumber(evalNode(node.right))
    if (r.t === 'err') return r
    let v
    switch (op) {
      case '+':
        v = l.v + r.v
        break
      case '-':
        v = l.v - r.v
        break
      case '*':
        v = l.v * r.v
        break
      case '/':
        if (r.v === 0) return ERR('#DIV/0!')
        v = l.v / r.v
        break
      case '^':
        v = Math.pow(l.v, r.v)
        break
      default:
        throw new Error('bad op: ' + op)
    }
    return finishArith(v)
  }

  function evalArgList(node) {
    if (node.type === 'range') return expandRangeValues(node.from, node.to)
    return [evalNode(node)]
  }

  function evalCall(node) {
    const spec = FUNCS[node.name]
    if (!spec) return ERR('#NAME?')
    if (node.args.length < spec.min || node.args.length > spec.max) return ERR('#ERR!')
    if (node.name === 'IF') return evalIf(node)

    const values = []
    for (const a of node.args) values.push(...evalArgList(a))

    if (node.name === 'COUNT') {
      const err = values.find((v) => v.t === 'err')
      if (err) return err
      return NUM(values.filter((v) => v.t === 'num').length)
    }

    const nums = values.map(toNumber)
    const err = nums.find((v) => v.t === 'err')
    if (err) return err
    const nn = nums.map((v) => v.v)
    let result
    switch (node.name) {
      case 'SUM':
        result = nn.reduce((a, b) => a + b, 0)
        break
      case 'MIN':
        result = Math.min(...nn)
        break
      case 'MAX':
        result = Math.max(...nn)
        break
      case 'AVG':
        result = nn.reduce((a, b) => a + b, 0) / nn.length
        break
      case 'ABS':
        result = Math.abs(nn[0])
        break
      default:
        throw new Error('bad function: ' + node.name)
    }
    return finishArith(result)
  }

  function evalIf(node) {
    const [condNode, thenNode, elseNode] = node.args
    const condList = evalArgList(condNode)
    const condErr = condList.find((v) => v.t === 'err')
    if (condErr) return condErr
    const condVal = condList[0]
    let boolResult
    if (condVal.t === 'bool') boolResult = condVal.v
    else if (condVal.t === 'num') boolResult = condVal.v !== 0
    else return ERR('#VALUE!')
    const branchNode = boolResult ? thenNode : elseNode
    const branchList = evalArgList(branchNode)
    return branchList[0]
  }

  return { evalCell }
}
"}

