 * Static dependency analysis of a formula's AST: every distinct in-range
 * address it names directly, ranges expanded. Independent of evaluation,
 * so an untaken IF branch or a misplaced range still names its cells.
 */

import { parseAddress, expandRangeAddrs, compareAddrKeys } from './address.js'

function walk(node, out) {
  if (!node) return
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'ref': {
      const a = parseAddress(node.text)
      if (a) out.add(a.key)
      return
    }
    case 'range': {
      const addrs = expandRangeAddrs(node.from, node.to)
      if (addrs) for (const a of addrs) out.add(a.key)
      return
    }
    case 'unary':
      walk(node.operand, out)
      return
    case 'bin':
      walk(node.left, out)
      walk(node.right, out)
      return
    case 'call':
      for (const a of node.args) walk(a, out)
      return
    default:
      throw new Error('bad node: ' + node.type)
  }
}

/** Returns sorted array of address keys named by a cell's content (formula only). */
export function collectDeps(cell) {
  if (!cell || cell.kind !== 'formula' || !cell.ast) return []
  const out = new Set()
  walk(cell.ast, out)
  return [...out].sort(compareAddrKeys)
}
"}

