content.arguments:
{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { parseInput } from './parse.js'
import { mergeDocs } from './merge.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
    process.exit(2)
  }

  let mine, base, theirs
  try {
    const raw = readStdin()
    ;({ mine, base, theirs } = parseInput(raw))
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }

  const regions = mergeDocs(mine, base, theirs)

  const out = []
  let conflict = false

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`)
      } else {
        out.push(`${region.kind} ${region.lines.length}\n`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const line of region.mine) out.push(`${line}\n`)
        if (mode === 'merge') {
          out.push('||||||| base\n')
          for (const line of region.base) out.push(`${line}\n`)
        }
        out.push('=======\n')
        for (const line of region.theirs) out.push(`${line}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const line of region.lines) out.push(`${line}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

main()
"}

