{"file_path":"src/diff.js","content":"/**
 * Line diff of one document against the base, driven by a longest common
 * subsequence over whole lines compared as exact strings.
 */

/**
 * The table of suffix LCS lengths: `table[i][j]` is the length of the longest
 * common subsequence of `base.slice(i)` and `side.slice(j)`.
 */
function suffixLcsTable(base, side) {
  const n = base.length
  const m = side.length
  const table = new Array(n + 1)
  for (let i = n; i >= 0; i -= 1) {
    table[i] = new Int32Array(m + 1)
  }
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  return table
}

/**
 * The matched line pairs of the earliest longest common subsequence: walking
 * both documents from the start, a match is taken whenever the two current
 * lines are equal, and otherwise the side whose remaining subsequence is at
 * least as long as the other's advances, the base winning ties.
 */
function matchPairs(base, side) {
  const table = suffixLcsTable(base, side)
  const pairs = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      pairs.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return pairs
}

/**
 * The changes of `side` against `base`: every stretch the common subsequence
 * does not cover, as a run of base lines replaced by a run of side lines.
 * Each change is `{ baseStart, baseEnd, sideStart, sideEnd }` with ends
 * exclusive, so an insertion has `baseStart === baseEnd` and a deletion has
 * `sideStart === sideEnd`.
 */
export function diffChanges(base, side) {
  const changes = []
  let baseAt = 0
  let sideAt = 0
  const push = (baseEnd, sideEnd) => {
    if (baseEnd > baseAt || sideEnd > sideAt) {
      changes.push({ baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [i, j] of matchPairs(base, side)) {
    push(i, j)
    baseAt = i + 1
    sideAt = j + 1
  }
  push(base.length, side.length)
  return changes
}
"}

