/** The merged document, conflicts written out with markers. */
export function renderMerge(regions, { withBase }) {
  const lines = []
  for (const region of regions) {
    if (region.kind !== 'conflict') {
      lines.push(...region.lines)
      continue
    }
    lines.push('<<<<<<< mine', ...region.mine)
    if (withBase) lines.push('||||||| base', ...region.base)
    lines.push('=======', ...region.theirs, '>>>>>>> theirs')
  }
  return lines
}

/** One line per region, naming its kind and counting its lines. */
export function renderRegions(regions) {
  return regions.map(region =>
    region.kind === 'conflict'
      ? `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`
      : `${region.kind} ${region.lines.length}`,
  )
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { mergeRegions } from './merge.js'
import { renderMerge, renderRegions } from './render.js'

const MODES = new Set(['merge', 'merge2', 'regions'])
const SEPARATOR = '%%%'

/** Ends the run with one line on standard error and nothing on standard output. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Everything standard input holds, as one string. */
async function readInput() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map(chunk => Buffer.from(chunk))).toString('utf8')
}

/**
 * The three documents the input holds: it is split on newlines, the empty tail
 * a trailing newline leaves is dropped, and a line that is exactly `%%%`
 * separates one document from the next.
 */
function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  return parts
}

const mode = process.argv[2]
if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

const [mine, base, theirs] = parseInput(await readInput())
const regions = mergeRegions(mine, base, theirs)
const lines =
  mode === 'regions' ? renderRegions(regions) : renderMerge(regions, { withBase: mode === 'merge' })

process.stdout.write(lines.map(line => `${line}\n`).join(''))
process.exitCode = regions.some(region => region.kind === 'conflict') ? 1 : 0
"}

