function depsOf(adjacency, name) {
  return adjacency.get(name) || new Set()
}

/**
 * Simulate the build on a fixed number of workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-index free worker whenever both are available at the current
 * instant.
 */
export function pack(tasks, adjacency, workers) {
  const names = [...tasks.keys()].sort()
  const priority = computePriorities(tasks, adjacency)

  const workerFree = new Array(workers).fill(0)
  const assignments = Array.from({ length: workers }, () => [])
  const finish = new Map()
  const started = new Set()

  const remaining = new Set(names)

  let t = 0
  while (remaining.size > 0) {
    // Assign as much as possible at the current instant t.
    for (;;) {
      const freeWorkers = []
      for (let i = 0; i < workers; i += 1) {
        if (workerFree[i] <= t) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      let best = null
      for (const name of remaining) {
        const deps = [...depsOf(adjacency, name)]
        const ready = deps.every((d) => finish.has(d) && finish.get(d) <= t)
        if (!ready) continue
        if (
          best === null ||
          priority(name) > priority(best) ||
          (priority(name) === priority(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const worker = freeWorkers[0]
      const cost = tasks.get(best)
      const start = t
      const end = t + cost
      assignments[worker].push({ name: best, start, finish: end })
      workerFree[worker] = end
      finish.set(best, end)
      remaining.delete(best)
      started.add(best)
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workers; i += 1) {
      if (workerFree[i] > t && workerFree[i] < next) next = workerFree[i]
    }
    t = next
  }

  const makespan = names.length === 0 ? 0 : Math.max(...names.map((n) => finish.get(n)))
  return { assignments, makespan }
}
"}

