/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle, computeDepths, computeTimes } from './graph.js'
import { pack } from './schedule.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    return { mode: 'pack', workersArg: argv[1] }
  }
  throw new CliError('usage: cli.js waves|explain|pack <workers>', 2)
}

function run(argv, input) {
  const { mode, workersArg } = parseArgs(argv)

  let workers
  if (mode === 'pack') {
    if (!WORKERS_RE.test(workersArg)) {
      throw new CliError('workers must be a positive integer', 2)
    }
    workers = parseInt(workersArg, 10)
  }

  const { tasks, adjacency } = parseGraph(input)

  const cycle = findCycle(tasks, adjacency)
  if (cycle) {
    throw new CliError(`cycle: ${cycle.join(' -> ')}`, 3)
  }

  const names = [...tasks.keys()].sort()
  const { start, finish } = computeTimes(tasks, adjacency)
  const total = names.length === 0 ? 0 : Math.max(...names.map((n) => finish(n)))

  if (mode === 'waves') {
    const depth = computeDepths(tasks, adjacency)
    const byDepth = new Map()
    for (const name of names) {
      const d = depth(name)
      if (!byDepth.has(d)) byDepth.set(d, [])
      byDepth.get(d).push(name)
    }
    const depths = [...byDepth.keys()].sort((a, b) => a - b)
    const lines = depths.map((d) => `wave ${d}: ${byDepth.get(d).join(' ')}`)
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

  if (mode === 'explain') {
    const depth = computeDepths(tasks, adjacency)
    const lines = names.map(
      (name) => `${name} start=${start(name)} finish=${finish(name)} depth=${depth(name)}`,
    )
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

  const { assignments, makespan } = pack(tasks, adjacency, workers)
  const lines = []
  for (let i = 0; i < workers; i += 1) {
    const entries = assignments[i].map((a) => ` ${a.name}@${a.start}-${a.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  try {
    // Parse arguments before consuming stdin so usage failures do not
    // depend on what (if anything) is piped in.
    parseArgs(argv)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exitCode = err.code
      return
    }
    throw err
  }

  const input = await readStdin()

  try {
    const output = run(argv, input)
    process.stdout.write(output)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exitCode = err.code
      return
    }
    throw err
  }
}

main()
"}

