{"file_path":"src/parse.js","content":"/**
 * Parsing and validation of a limiter file into declarations and events.
 */

const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function isName(word) {
  return TOKEN_RE.test(word)
}

function integerAtLeast(word, field, least, line) {
  if (!INT_RE.test(word)) throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < BigInt(least)) throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  return value
}

/**
 * Splits the source into logical lines, dropping the empty tail that a
 * trailing newline leaves behind.
 */
export function splitLines(source) {
  const lines = source.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '' && source.endsWith('\n')) lines.pop()
  return lines
}

/**
 * Parses a limiter file. Returns the declared policies in order, the routes,
 * and the event log.
 */
export function parse(source) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  const lines = splitLines(source)
  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const name = words[1]
      if (!isName(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      const capacity = integerAtLeast(words[2], 'capacity', 1, lineNo)
      const refill = integerAtLeast(words[3], 'refill', 0, lineNo)
      const per = integerAtLeast(words[4], 'per', 1, lineNo)
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (words.length !== 4) throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      const name = words[1]
      if (!isName(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      const limit = integerAtLeast(words[2], 'limit', 0, lineNo)
      const span = integerAtLeast(words[3], 'span', 1, lineNo)
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (words.length < 3) throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isName(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      const named = []
      for (const word of words.slice(2)) {
        if (!isName(word)) throw new ParseError(lineNo, `invalid policy name ${word}`)
        if (!policies.has(word)) throw new ParseError(lineNo, `unknown policy ${word}`)
        named.push(word)
      }
      routes.set(prefix, named)
    } else if (directive === 'event') {
      if (words.length !== 3) throw new ParseError(lineNo, 'expected event <tick> <key>')
      const tick = integerAtLeast(words[1], 'tick', 0, lineNo)
      const key = words[2]
      if (!isName(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

{"file_path":"src/simulate.js","content":"/**
 * The limiter simulation: token buckets, sliding windows and routing.
 */

/** A token bucket, holding exact fractional tokens per key. */
class Bucket {
  constructor(spec) {
    this.name = spec.name
    this.capacity = spec.capacity
    this.refill = spec.refill
    this.per = spec.per
    this.states = new Map()
  }

  state(key, tick) {
    let entry = this.states.get(key)
    if (entry === undefined) {
      // A key first reaching the bucket finds it full.
      entry = { tokens: this.capacity * this.per, at: tick }
      this.states.set(key, entry)
    }
    return entry
  }

  advance(key, tick) {
    const entry = this.state(key, tick)
    const elapsed = tick - entry.at
    if (elapsed > 0n) {
      const ceiling = this.capacity * this.per
      entry.tokens += this.refill * elapsed
      if (entry.tokens > ceiling) entry.tokens = ceiling
      entry.at = tick
    }
  }

  allows(key, tick) {
    return this.state(key, tick).tokens >= this.per
  }

  record(key, tick) {
    this.state(key, tick).tokens -= this.per
  }
}

/** A sliding window remembering the ticks it recorded per key. */
class Window {
  constructor(spec) {
    this.name = spec.name
    this.limit = spec.limit
    this.span = spec.span
    this.states = new Map()
  }

  state(key) {
    let entry = this.states.get(key)
    if (entry === undefined) {
      entry = []
      this.states.set(key, entry)
    }
    return entry
  }

  advance(key, tick) {
    const ticks = this.state(key)
    const cutoff = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= cutoff) drop += 1
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.state(key).length) < this.limit
  }

  record(key, tick) {
    this.state(key).push(tick)
  }
}

function makePolicy(spec) {
  return spec.kind === 'bucket' ? new Bucket(spec) : new Window(spec)
}

/**
 * Runs the event log, returning one verdict per event in log order.
 */
export function simulate({ policies, routes, events }) {
  const runtime = new Map()
  for (const [name, spec] of policies) runtime.set(name, makePolicy(spec))

  const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)

  const verdicts = []
  for (const { tick, key } of events) {
    let chosen = null
    for (const prefix of prefixes) {
      if (key.startsWith(prefix)) {
        chosen = routes.get(prefix)
        break
      }
    }
    const chain = chosen === null ? [] : chosen.map((name) => runtime.get(name))
    for (const policy of chain) policy.advance(key, tick)
    let refused = null
    for (const policy of chain) {
      if (!policy.allows(key, tick)) {
        refused = policy.name
        break
      }
    }
    if (refused === null) {
      for (const policy of chain) policy.record(key, tick)
      verdicts.push({ tick, key, allowed: true })
    } else {
      verdicts.push({ tick, key, allowed: false, policy: refused })
    }
  }
  return verdicts
}
"}

