{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function replay(verdicts) {
  return verdicts
    .map((v) => (v.allowed ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.policy}\n`))
    .join('')
}

function summary(verdicts) {
  const perKey = new Map()
  let allowed = 0
  let denied = 0
  for (const v of verdicts) {
    let tally = perKey.get(v.key)
    if (tally === undefined) {
      tally = { allowed: 0, denied: 0 }
      perKey.set(v.key, tally)
    }
    if (v.allowed) {
      tally.allowed += 1
      allowed += 1
    } else {
      tally.denied += 1
      denied += 1
    }
  }
  const keys = [...perKey.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const key of keys) {
    const tally = perKey.get(key)
    out += `${key} allowed=${tally.allowed} denied=${tally.denied}\n`
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  let program
  try {
    program = parse(readStdin())
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }
  const verdicts = simulate(program)
  process.stdout.write(mode === 'replay' ? replay(verdicts) : summary(verdicts))
}

main(process.argv.slice(2))
"}

